type BackupModule=typeof sqlite&{backup?:(source:DatabaseSync,path:string,options:{rate:number;progress:(info:{totalPages:number;remainingPages:number})=>void})=>Promise<number>}
async function onlineBackup(sourcePath:string,targetPath:string):Promise<void> {const backup=(sqlite as BackupModule).backup;if(typeof backup!=='function')throw new Error('当前 Node 不支持 SQLite 在线备份');const source=db(sourcePath,true);try{await backup(source,targetPath,{rate:256,progress:()=>{}})}finally{source.close()}}
