function copiedSnapshotFiles(snapshots:DatabaseSnapshot[]):Revision[]{return snapshots.flatMap(snapshot=>snapshot.files.map(item=>item.revision))}
function safeConfig(root:string):string|null{return readBounded(join(root,'config.toml'),1024*1024)}
